            if (-not $proc.WaitForExit($Timeout * 1000)) {
                $surv = Stop-ProcessTree -Process $proc   # [int[]]; never wrap in @()
                $t.Problem = "timeout after $Timeout s (process tree killed)"
                if ($surv.Count -gt 0) {
