                        Write-PendingFile -Path $pendingPath -Record $pendingRecord
                    } catch { }
                }
            } else {
                $t.Exit = $proc.ExitCode
            }
        }
    }
    $watch.Stop()
    $t.Wall = [math]::Round($watch.Elapsed.TotalSeconds, 1)
