        $panelResults[[int]$pm.Entry.Position] = [pscustomobject]@{ Exit = $childExit; Entry = $memberEntry; Refusal = $(if ($refusal) { $refusal -replace '^codex-consult: ', '' } else { "exit $childExit" }); NotStarted = '' }
